import{_ as e,o,c as a,ag as n}from"./chunks/framework.qXLDknWC.js";const p=JSON.parse('{"title":"AI Agent","description":"","frontmatter":{},"headers":[],"relativePath":"features/ai-agent.md","filePath":"features/ai-agent.md"}'),r={name:"features/ai-agent.md"};function s(l,t,i,h,d,g){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="ai-agent" tabindex="-1">AI Agent <a class="header-anchor" href="#ai-agent" aria-label="Permalink to &quot;AI Agent&quot;">​</a></h1><p>The <strong>Agent</strong> is a chat that <strong>writes</strong> the open character or lorebook. You ask for a fill, a rewrite, or a cut, and it updates the card (or book) itself. Orion stays the assistant that talks back without changing fields unless you copy from it.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The Agent needs an AI provider, same as Orion. See <a href="/CharacterVault/docs/configuration/ai-setup">AI Setup</a>.</p><p>It can use the <strong>global</strong> model from <strong>Settings → AI Config</strong>, or its own mapping on <strong>Settings → Prompts → Agent</strong>. Toolbars and Orion are separate.</p></div><div class="warning custom-block"><p class="custom-block-title">It writes for real</p><p>When a run finishes, changes land in this card or book. A banner in the editor says so while it is working. Use <a href="/CharacterVault/docs/features/snapshots-history">Snapshots</a> if you need to roll back.</p></div><h2 id="orion-vs-agent" tabindex="-1">Orion vs Agent <a class="header-anchor" href="#orion-vs-agent" aria-label="Permalink to &quot;Orion vs Agent&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;"><strong>Orion</strong></th><th style="text-align:left;"><strong>Agent</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Job</strong></td><td style="text-align:left;">Brainstorm, Q&amp;A, drafts in chat</td><td style="text-align:left;">Fill and revise the open card or book</td></tr><tr><td style="text-align:left;"><strong>Writes the card?</strong></td><td style="text-align:left;">No</td><td style="text-align:left;">Yes, when the run finishes</td></tr><tr><td style="text-align:left;"><strong>Context</strong></td><td style="text-align:left;">Sections you pin, plus optional custom notes</td><td style="text-align:left;">Field and entry catalogs, plus optional custom notes. It reads bodies with tools.</td></tr><tr><td style="text-align:left;"><strong>Model</strong></td><td style="text-align:left;">Always <strong>Settings → AI Config</strong></td><td style="text-align:left;"><strong>Settings → Prompts → Agent</strong>, or AI Config if you leave Default</td></tr><tr><td style="text-align:left;"><strong>Where</strong></td><td style="text-align:left;">Character workspace and lorebook vault workspace</td><td style="text-align:left;">Same two workspaces, behind the <strong>Agent</strong> toggle</td></tr></tbody></table><p>You can switch back to Orion at any time. The two chats do not share a thread.</p><p>To open Agent by default, set <strong>Settings → Studio → Chat panel</strong> to <strong>Agent</strong>. That applies the next time you open a character or lorebook. The header toggle still works for the current session.</p><h2 id="opening-the-agent" tabindex="-1">Opening the Agent <a class="header-anchor" href="#opening-the-agent" aria-label="Permalink to &quot;Opening the Agent&quot;">​</a></h2><h3 id="on-a-character" tabindex="-1">On a character <a class="header-anchor" href="#on-a-character" aria-label="Permalink to &quot;On a character&quot;">​</a></h3><ol><li>Open the character in the workspace.</li><li>Open the <strong>Ask AI</strong> panel (right side; header toggle).</li><li>Click <strong>Agent</strong> in the chat header so it stays on (skip this if Agent is already your Studio default).</li><li>Type what you want written. <strong>Enter</strong> sends; <strong>Shift+Enter</strong> adds a line.</li></ol><p>The left <strong>AI Context</strong> panel still has <a href="/CharacterVault/docs/features/ai-context#custom-context">custom context</a>. Section pins hide in Agent mode; they come back when you switch to Orion. The Agent reads the card through tools, so you do not pick Description vs Personality by hand.</p><h3 id="on-a-standalone-lorebook" tabindex="-1">On a standalone lorebook <a class="header-anchor" href="#on-a-standalone-lorebook" aria-label="Permalink to &quot;On a standalone lorebook&quot;">​</a></h3><ol><li>Open a book from the home <strong>Lorebooks</strong> tab.</li><li>Open the chat panel.</li><li>Click <strong>Agent</strong>.</li><li>Ask it to add or revise entries in <strong>this</strong> book.</li></ol><p>That lorebook Agent does not edit character spec fields. For description, greetings, and the book <strong>on a card</strong>, use the character Agent.</p><h2 id="what-it-can-write" tabindex="-1">What it can write <a class="header-anchor" href="#what-it-can-write" aria-label="Permalink to &quot;What it can write&quot;">​</a></h2><h3 id="character-agent" tabindex="-1">Character Agent <a class="header-anchor" href="#character-agent" aria-label="Permalink to &quot;Character Agent&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Area</th><th style="text-align:left;">What you can ask</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Card fields</strong></td><td style="text-align:left;">Name, description, personality, scenario, first message, examples, system prompt, post-history instructions, appearance, creator notes, creator, character version, tags, avatar URL</td></tr><tr><td style="text-align:left;"><strong>Alternate greetings</strong></td><td style="text-align:left;">Add, rewrite, snippet-edit, or delete. <strong>Greeting 1</strong> is the first alternate, same as the <a href="/CharacterVault/docs/features/greetings-editor">Greetings</a> tab. First Message is its own field.</td></tr><tr><td style="text-align:left;"><strong>Embedded lorebook</strong></td><td style="text-align:left;">Add, rename, rekey, rewrite, snippet-edit, or delete entries (name, keys, content, constant)</td></tr></tbody></table><h3 id="lorebook-agent" tabindex="-1">Lorebook Agent <a class="header-anchor" href="#lorebook-agent" aria-label="Permalink to &quot;Lorebook Agent&quot;">​</a></h3><p>Same lorebook entry tools as above, for the vault book you have open.</p><h3 id="what-it-does-not-write" tabindex="-1">What it does not write <a class="header-anchor" href="#what-it-does-not-write" aria-label="Permalink to &quot;What it does not write&quot;">​</a></h3><ul><li>Portrait <strong>image</strong> (upload that yourself)</li><li>SillyTavern extras such as recursion flags, probability, depth, scan settings, or the Extensions JSON blob</li><li>The whole vault at once (it only sees the open card or book)</li></ul><p>New lorebook entries it adds are <strong>not</strong> pinned into Orion or the AI toolbar. Open the entry <strong>eye</strong> if you want them in that context. They still export on the card or book.</p><p>If the character has a <a href="/CharacterVault/docs/features/lorebook-vault#attach-to-a-character-vault-local">linked library book</a>, lorebook writes on the character Agent also update that library book when the run finishes.</p><h2 id="custom-context" tabindex="-1">Custom context <a class="header-anchor" href="#custom-context" aria-label="Permalink to &quot;Custom context&quot;">​</a></h2><p>Optional source notes (world bible, outline, paste dump) live in <strong>AI Context → Custom</strong>. Enable the block if you want the Agent to treat it as material. It is still vault-local: not on the PNG/JSON card, not in SillyTavern fields.</p><p>The Agent prefers filling empty fields and staying consistent with those notes. You do not have to pin card sections.</p><p>Details: <a href="/CharacterVault/docs/features/ai-context#custom-context">AI Context → Custom Context</a>.</p><h2 id="how-a-run-works" tabindex="-1">How a run works <a class="header-anchor" href="#how-a-run-works" aria-label="Permalink to &quot;How a run works&quot;">​</a></h2><ol><li>You send a request.</li><li>The Agent sees <strong>catalogs</strong> (field ids and sizes; lorebook ids, names, and keys) plus custom context if enabled. It reads full bodies only for what it is about to change.</li><li>It calls tools (list, read, update, replace, add, delete). The chat shows short colored tool lines, not the full field text.</li><li>When it is done (or you <strong>Stop</strong>), CharacterVault <strong>writes once</strong> and takes <strong>one snapshot</strong> first.</li></ol><p>Until that write, the editor keeps the previous text. The banner <strong>Agent is writing. Changes appear when the run finishes</strong> is the cue.</p><p>Snippet edits match a unique stretch of existing text instead of rewriting the whole field or entry. Matching tolerates quote styles and multi-section spans. If the snippet is not unique, ask it to re-read and copy a longer stretch.</p><p>Providers that accept OpenAI-style <code>tools</code> use native function calling. If a provider rejects that, the Agent falls back to XML tool calls in the message. You do not turn this on separately.</p><p>Catalogs in the prompt are built at the <strong>start</strong> of the run. After names or keys change, the Agent can list again in that same run. The <strong>next</strong> Send rebuilds catalogs from the saved card.</p><h3 id="what-you-see-in-chat" tabindex="-1">What you see in chat <a class="header-anchor" href="#what-you-see-in-chat" aria-label="Permalink to &quot;What you see in chat&quot;">​</a></h3><ul><li><strong>Tool lines:</strong> color-coded list / read / write results, including lorebook entry ids</li><li><strong>Thinking:</strong> streams in an expanded <strong>Thinking</strong> fold while it is live; after the reply it collapses</li><li><strong>Live token count:</strong> catalogs, custom context, and the current prompt (including tool results)</li><li><strong>TTFT / t/s:</strong> on the assistant message info tooltip when the reply finishes, same as Orion</li><li>Lookup-only reads do not add extra assistant turns; those bodies count in the live meter, then drop out of the transcript</li></ul><p>Long threads keep the last <strong>100</strong> messages in the panel so the tab stays light.</p><h3 id="chat-controls" tabindex="-1">Chat controls <a class="header-anchor" href="#chat-controls" aria-label="Permalink to &quot;Chat controls&quot;">​</a></h3><ul><li><strong>Stop</strong> (square while it is working) cancels the current run. Writes that already finished in that run still flush.</li><li><strong>Send</strong> with an empty box retries the last request (same as the composer hint).</li><li><strong>New chat</strong> clears the thread. The card stays as last written.</li><li>Delete a message to trim from that point; you cannot delete while a run is in progress.</li></ul><p>If you Stop while it is still thinking, Send is available again so you can retry or type a new ask.</p><h2 id="context-meter" tabindex="-1">Context meter <a class="header-anchor" href="#context-meter" aria-label="Permalink to &quot;Context meter&quot;">​</a></h2><p>The Agent chat shows estimated tokens for catalogs, custom context, and the live prompt while a run is going. Lookup reads (full field or entry bodies) count in that live number, then drop out of the transcript so the thread does not keep those bodies.</p><p>Idle, the meter is catalogs + custom context + what is still in the chat. Raise <strong>Settings → Sampler → Context Length</strong> if large books run close to the limit.</p><p>The sampler <strong>Max Tokens</strong> slider does not cap Agent output the same way. Agent completions use a larger output budget so tool calls are less likely to cut off.</p><h2 id="model-for-agent" tabindex="-1">Model for Agent <a class="header-anchor" href="#model-for-agent" aria-label="Permalink to &quot;Model for Agent&quot;">​</a></h2><p>On <strong>Settings → Prompts</strong>, the <strong>Agent</strong> card at the top uses the same picker as toolbar ops:</p><ul><li><strong>Default (AI Config)</strong> to keep the global model</li><li>Or pick an endpoint you already configured and a model id</li></ul><p>Keys stay on <strong>AI Config</strong>. Save Settings before the mapping applies. Character Agent and lorebook Agent share this one mapping.</p><p>The Agent is <strong>not</strong> Orion with extra buttons. It has to emit valid tool calls, often several in a row. A model that chats well can still fail here.</p><p>Point Agent at a <strong>current tool-calling / agentic</strong> model. Leave a cheap chat model on <strong>AI Config</strong> for Orion and Fix if you want; do not make the Agent use that same model.</p><p>See <a href="/CharacterVault/docs/configuration/ai-setup#prompts-tab">AI Setup → Prompts Tab</a>. If tool calls fail, see <a href="#troubleshooting">Troubleshooting</a>.</p><h2 id="limits-per-run" tabindex="-1">Limits (per run) <a class="header-anchor" href="#limits-per-run" aria-label="Permalink to &quot;Limits (per run)&quot;">​</a></h2><p>If a job is huge, send a second ask for the rest.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Cap</th><th style="text-align:left;">About</th></tr></thead><tbody><tr><td style="text-align:left;">Field updates</td><td style="text-align:left;">30</td></tr><tr><td style="text-align:left;">Greeting add/update/delete</td><td style="text-align:left;">20</td></tr><tr><td style="text-align:left;">Lorebook add / update / delete</td><td style="text-align:left;">50 each</td></tr><tr><td style="text-align:left;">Tool calls in one model reply</td><td style="text-align:left;">12</td></tr><tr><td style="text-align:left;">Loop turns</td><td style="text-align:left;">32</td></tr></tbody></table><p>Duplicate lorebook <strong>names</strong> in one run revise the new entry instead of adding a second copy. Names that already existed in the book are rejected; ask it to update that id.</p><h2 id="snapshots" tabindex="-1">Snapshots <a class="header-anchor" href="#snapshots" aria-label="Permalink to &quot;Snapshots&quot;">​</a></h2><p>Before the Agent writes, CharacterVault stores one snapshot of the current card or book (if something actually changed). <strong>Opened card</strong> / <strong>Opened</strong> stays last in the list and cannot be deleted.</p><p>Open <strong>Snapshots</strong> (character) or <strong>History</strong> (vault book) to compare and restore. Linked characters follow a restored library book, same as a manual restore.</p><p><a href="/CharacterVault/docs/features/snapshots-history">Snapshots &amp; Rollback</a></p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Put source notes in <strong>custom context</strong>, then ask for a fill or a pass (thin description, rename keys, add missing entries).</li><li>Prefer one clear job per Send. Split “rewrite description” and “rebuild the lorebook” if either is large.</li><li><strong>Stop</strong>, then empty <strong>Send</strong>, retries the last user message.</li><li>After a run, skim Snapshots if the write was bigger than you meant.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting {#troubleshooting}&quot;">​</a></h2><p>Most “the Agent is broken” reports are the <strong>model</strong>. CharacterVault can only run the tools the model actually calls. If the model cannot do function calling, no setting will save the run.</p><h3 id="tool-calls-fail-loop-or-never-write-the-card" tabindex="-1">Tool calls fail, loop, or never write the card <a class="header-anchor" href="#tool-calls-fail-loop-or-never-write-the-card" aria-label="Permalink to &quot;Tool calls fail, loop, or never write the card&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Switch to a newer model that is trained for tools. That is the fix.</p></div><p>A small chat model, a roleplay finetune, or last year’s instruct weights will invent XML, call <code>tool_name</code>, skip tools and “helpfully” dump prose, or loop the same empty call. That is expected. Those models were not trained for this job.</p><p>Size is not enough. An old 70B chat model still loses to a current ~27B that was post-trained for agents. <strong>Qwen3.8-27B</strong> (released August 2026) is a dense open-weight example that handles this Agent well, including the <strong>Thinking</strong> listing on NanoGPT. Hosted names look like <code>qwen3.8-27b</code> / <code>qwen3.8-27b:thinking</code> (NanoGPT) or <code>qwen/qwen3.8-27b</code> (OpenRouter). Fetch the catalog; do not type a guessed slug.</p><p>Other current families that are actually built for multi-step tool use (as of August 2026):</p><table tabindex="0"><thead><tr><th style="text-align:left;">Family</th><th style="text-align:left;">Why it belongs here</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Qwen3.8</strong></td><td style="text-align:left;"><strong>Qwen3.8-27B</strong> for a compact pick; <strong>Qwen3.8-Max</strong> if you want the flagship</td></tr><tr><td style="text-align:left;"><strong>DeepSeek V4</strong></td><td style="text-align:left;"><strong>V4 Pro</strong> (or Flash if you need cheaper / faster)</td></tr><tr><td style="text-align:left;"><strong>GLM-5.3</strong></td><td style="text-align:left;">Current GLM coding/agent stack; <strong>GLM-5.2</strong> is the previous one</td></tr><tr><td style="text-align:left;"><strong>Kimi K3</strong></td><td style="text-align:left;">Current Kimi flagship; older <strong>K2.5 / K2.6</strong> are a generation behind</td></tr><tr><td style="text-align:left;"><strong>GPT-5.6 / Claude Opus 4.8</strong> class</td><td style="text-align:left;">Fine via OpenRouter or another compatible gateway if you already pay for them</td></tr><tr><td style="text-align:left;"><strong>Gemma 4</strong> (local)</td><td style="text-align:left;">Native tool calling across the lineup, including the small <strong>E2B</strong> / <strong>E4B</strong> cuts. See <a href="#local-models">Local models</a>.</td></tr></tbody></table><p>Do <strong>not</strong> use for Agent:</p><ul><li>Small chat/instruct models with <strong>no</strong> tool-calling post-training (generic 7B–8B chat is not the same as <strong>Gemma 4 E2B / E4B</strong>)</li><li>Roleplay, NSFW, or “uncensored chat” finetunes unless you have already seen them emit clean native <code>tool_calls</code> on a real Agent run</li><li>Older lines: <strong>Llama 3.x</strong> chat, <strong>Qwen2.5</strong>, <strong>Qwen3</strong> 8B/14B as your daily Agent, <strong>DeepSeek V3 / V3.1 / V3.2</strong>, <strong>GLM-4.x</strong>, <strong>Gemma 3</strong></li><li>Cheap <strong>mini / nano / flash</strong> SKUs sold for one-shot chat, unless the provider lists tools <strong>and</strong> a real Agent pass works</li></ul><p>Orion can stay on a weaker model. Map <strong>Settings → Prompts → Agent</strong> to one of the families above, save, and run again.</p><h3 id="local-models" tabindex="-1">Local models <a class="header-anchor" href="#local-models" aria-label="Permalink to &quot;Local models {#local-models}&quot;">​</a></h3><p>Local works if you pick models that were trained for tools. Point <strong>Settings → Prompts → Agent</strong> at your local endpoint (LM Studio, llama.cpp, Ollama, and so on).</p><p><strong>Gemma 4</strong> is the example. The whole lineup can call tools, including the small <strong>E2B</strong> and <strong>E4B</strong> cuts. E4B is already useful in practice (a pass that rekeys a dozen lorebook entries is in range). <strong>12B</strong>, <strong>26B-A4B</strong>, and <strong>31B</strong> hold up better as the job gets larger.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>More parameters plus tool-call training just works better. A 4B that knows tools will beat a 70B that does not. Between two tool-trained models, the bigger one is the safer pick for a full card or a whole-book rewrite.</p></div><h3 id="the-agent-talks-instead-of-editing" tabindex="-1">The Agent talks instead of editing <a class="header-anchor" href="#the-agent-talks-instead-of-editing" aria-label="Permalink to &quot;The Agent talks instead of editing&quot;">​</a></h3><p>It is chatting. A tool-capable model reads catalogs and calls <code>list</code> / <code>read</code> / <code>update</code> / <code>replace</code>. If you only get a paragraph in the chat and no colored tool lines, the model did not call tools. Same fix: newer tool-calling model.</p><h3 id="incomplete-action-or-cut-off-tool-json" tabindex="-1"><code>incomplete_action</code> or cut-off tool JSON <a class="header-anchor" href="#incomplete-action-or-cut-off-tool-json" aria-label="Permalink to &quot;`incomplete_action` or cut-off tool JSON&quot;">​</a></h3><p>The model started a call and ran out of output, or emitted broken JSON/XML. CharacterVault salvages truncated native calls when it can, then asks the model to finish. If that keeps happening:</p><ul><li>Use a model with <strong>native</strong> <code>tools</code> (not XML-in-chat)</li><li>Prefer a current tool-calling model (<strong>Qwen3.8</strong>, <strong>DeepSeek V4</strong>, <strong>GLM-5.3</strong>, <strong>Kimi K3</strong>, or <strong>Gemma 4</strong>) over a chat-only instruct</li><li>Split the job, or step up a size, if a small local keeps cutting off (“rewrite description” vs “rebuild the lorebook”)</li></ul><p>Agent output is <strong>not</strong> capped by the Sampler <strong>Max Tokens</strong> slider; raising that slider will not fix a model that cannot close a call.</p><h3 id="context-meter-is-full-prompt-too-long" tabindex="-1">Context meter is full / prompt too long <a class="header-anchor" href="#context-meter-is-full-prompt-too-long" aria-label="Permalink to &quot;Context meter is full / prompt too long&quot;">​</a></h3><p>Raise <strong>Settings → Sampler → Context Length</strong>. Huge books plus custom context plus a long thread will crowd the window. Start <strong>New chat</strong> if the thread is old; the card stays as last written. Lookup bodies count in the live meter, then drop out.</p><h3 id="changes-never-appear-in-the-editor" tabindex="-1">Changes never appear in the editor <a class="header-anchor" href="#changes-never-appear-in-the-editor" aria-label="Permalink to &quot;Changes never appear in the editor&quot;">​</a></h3><p>The Agent writes <strong>once</strong>, when the run finishes (or you <strong>Stop</strong>, for tools that already completed). The banner is the cue. If the run ends with no tool lines, nothing was applied. That is a model/tool failure, not a delayed save.</p><h3 id="lorebook-writes-did-not-reach-the-vault-book" tabindex="-1">Lorebook writes did not reach the vault book <a class="header-anchor" href="#lorebook-writes-did-not-reach-the-vault-book" aria-label="Permalink to &quot;Lorebook writes did not reach the vault book&quot;">​</a></h3><p>The character must have a <a href="/CharacterVault/docs/features/lorebook-vault#attach-to-a-character-vault-local">linked library book</a>. Unlinked card books stay on the character only.</p><h3 id="wrong-greeting-number" tabindex="-1">Wrong greeting number <a class="header-anchor" href="#wrong-greeting-number" aria-label="Permalink to &quot;Wrong greeting number&quot;">​</a></h3><p><strong>Greeting 1</strong> is the first <em>alternate</em>, same as the editor. First Message is a separate field. Ask for “greeting 1” or “first message” explicitly.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/features/ai-assistant">AI Assistant Orion</a> (chat that does not write the card)</li><li><a href="/CharacterVault/docs/features/ai-context">AI Context Panel</a></li><li><a href="/CharacterVault/docs/configuration/ai-setup#prompts-tab">Configure the Agent model</a></li><li><a href="/CharacterVault/docs/features/snapshots-history">Snapshots &amp; Rollback</a></li><li><a href="/CharacterVault/docs/features/greetings-editor">Greetings Editor</a></li><li><a href="/CharacterVault/docs/features/lorebook-editor">Lorebook Editor</a></li><li><a href="/CharacterVault/docs/features/lorebook-vault">Lorebook Vault</a></li></ul>',92)])])}const u=e(r,[["render",s]]);export{p as __pageData,u as default};
